// Busca en la ejecución que falló qué se estaba procesando y decide qué hacer: en 03 marcar la liquidación, en 01 sacar el correo de la carpeta
const aviso = $('Error Trigger').first().json;
const ejecucion = $input.first().json;
const runData = (ejecucion && ejecucion.data && ejecucion.data.resultData && ejecucion.data.resultData.runData) || {};
const salida = nodo => runData[nodo]?.[0]?.data?.main?.[0]?.[0]?.json;
const leida = Boolean(ejecucion && ejecucion.data);

const esLiquidaciones = aviso.workflow?.id === 'CfNMFXcjUOEGDpWo';
const esExtraccion = aviso.workflow?.id === 'zO613EETvS4k2W0O';

// 03 - Envía ERM Liquidación
const cabecera = (esLiquidaciones && (salida('Recuperamos fecha y hora') || salida('Leer cabezera'))) || {};
const idProceso = esLiquidaciones
  ? (cabecera.id_proceso || salida('Update Estado')?.id_proceso || salida('Tomamos solo una')?.id_proceso || '')
  : '';
const estadoFinal = Boolean(runData['Update enviada'] || runData['Update error']);
const yaLlamadoT2000 = Boolean(runData['Enviamos API T2000']) && !estadoFinal;
const marcar = Boolean(idProceso) && !yaLlamadoT2000 && !estadoFinal;

// 01 - Extrae de Outlook
const correo = (esExtraccion && (salida('Generar ID Datos') || salida('Filtramos firmas') || salida('Get many folder messages'))) || {};
const mensajeId = correo.message_id || correo.id || '';
const correoMovido = Boolean(runData['Facturas procesadas'] || runData['Facturas Error']);
const registrada = Boolean(runData['Actualizamos En proceso']);
const mover = esExtraccion && Boolean(mensajeId) && !correoMovido;

const error = aviso.execution?.error || aviso.trigger?.error || {};
const nodo = aviso.execution?.lastNodeExecuted || '';
const mensaje = error.message || 'Error sin mensaje';

let estadoHoja = 'Sin cambios.';
if (marcar) estadoHoja = 'Marcada como Rechazada. Para reintentar, vuelve a ponerla en OK.';
else if (yaLlamadoT2000) estadoHoja = 'Sin cambios (sigue en "A Liquidación"): ya se había llamado a T2000. Comprueba en T2000 si llegó antes de volver a ponerla en OK.';
else if (estadoFinal) estadoHoja = 'Sin cambios: la fila ya tenía su estado final (Enviada o Rechazada).';
else if (mover && registrada) estadoHoja = 'Correo movido a la carpeta Errores. La liquidación ya estaba registrada en la hoja' + (correo.id_proceso ? ' (' + correo.id_proceso + ')' : '') + ', así que seguirá su curso.';
else if (mover) estadoHoja = 'Correo movido a la carpeta Errores sin registrar nada. Para reintentar, vuelve a moverlo a la carpeta Liquidaciones.';
else if (esExtraccion && correoMovido) estadoHoja = 'Sin cambios: el correo ya se había movido de la carpeta.';
else if (esExtraccion) estadoHoja = 'No se ha llegado a leer ningún correo' + (leida ? '.' : ' (no se pudo leer la ejecución).');
else if (esLiquidaciones) estadoHoja = 'No se ha podido identificar la liquidación' + (leida ? '.' : ' (no se pudo leer la ejecución).');

return [{
  json: {
    flujo: aviso.workflow?.name || '',
    nodo,
    mensaje,
    enlace: aviso.execution?.url || '',
    id_proceso: idProceso,
    numero_factura: cabecera.numero_factura ? String(cabecera.numero_factura) : '',
    emisor_nombre: cabecera.emisor_nombre || '',
    correo_asunto: correo.asunto_email || correo.subject || '',
    mensaje_id: mensajeId,
    marcar_rechazada: marcar,
    mover_a_errores: mover,
    estado_hoja: estadoHoja,
    motivo: ('Error en n8n (' + nodo + '): ' + mensaje).slice(0, 500)
  }
}];

